INSERT INTO `pages` (`slug`, `content`) VALUES ('legals', '{"heading":{"eyebrow":{"en":"Badagoni / Website information","ka":""},"title":{"en":"Legals","ka":""},"subtitle":{"en":"Terms for using this website and information about your privacy.","ka":""}},"terms":{"eyebrow":{"en":"01 / Website information","ka":""},"title":{"en":"Terms and conditions","ka":""},"revisionLabel":{"en":"Draft for review","ka":""},"revisionDate":"2026-09-22","sections":[{"id":"about-this-website","type":"text","heading":{"en":"About this website","ka":""},"body":{"en":"This website introduces Badagoni, our wines, vineyards, and winemaking heritage. Badagoni’s contact details are JSC Badagoni, 4 Liberty Square, 0105 Tbilisi, Georgia, and office@badagoni.ge.","ka":""}},{"id":"age-and-responsible-enjoyment","type":"text","heading":{"en":"Age and responsible enjoyment","ka":""},"body":{"en":"Our wine content is intended for people of legal drinking age in their country of residence. Please enjoy alcohol responsibly and observe the rules that apply where you are.","ka":""}},{"id":"wine-information-and-enquiries","type":"text","heading":{"en":"Wine information and enquiries","ka":""},"body":{"en":"Wine descriptions, photographs, vintages, and awards are presented for information. Availability, packaging, and specifications may change. Please contact our team to confirm current details. This website does not accept online orders or payments, and sending an enquiry does not confirm a purchase, booking, or other agreement.","ka":""}},{"id":"content-and-intellectual-property","type":"text","heading":{"en":"Content and intellectual property","ka":""},"body":{"en":"The Badagoni name, logos, text, photographs, and other materials belong to their respective rights holders. You may browse the website and share links to its pages. Reuse of content must comply with any stated licence, permission from the relevant rights holder, and applicable law. Any specific image credit or licence remains applicable to that image.","ka":""}},{"id":"using-the-website","type":"text","heading":{"en":"Using the website","ka":""},"body":{"en":"Please use the website lawfully. Do not attempt to gain unauthorised access, interfere with its operation, introduce malicious software, or misuse the contact details and content published here.","ka":""}},{"id":"links-and-availability","type":"text","heading":{"en":"Links and availability","ka":""},"body":{"en":"Some links lead to other websites, including map services and original news sources. Those websites have their own terms and privacy practices. We aim to keep this website useful and accurate, but information and availability may change. Please let us know if you notice an error.","ka":""}},{"id":"your-rights-and-these-terms","type":"text","heading":{"en":"Your rights and these terms","ka":""},"body":{"en":"Nothing in these terms is intended to exclude rights or protections that cannot be excluded under applicable law. These terms may be updated as the website develops. For questions about the website or these terms, write to office@badagoni.ge.","ka":""}}]},"privacy":{"eyebrow":{"en":"02 / Website information","ka":""},"title":{"en":"Privacy policy","ka":""},"revisionLabel":{"en":"Draft for review","ka":""},"revisionDate":"2026-09-22","sections":[{"id":"scope-and-contact","type":"text","heading":{"en":"Scope and contact","ka":""},"body":{"en":"This notice concerns this Badagoni website and enquiries sent using its contact links. For questions about your information, contact JSC Badagoni at office@badagoni.ge or 4 Liberty Square, 0105 Tbilisi, Georgia.","ka":""}},{"id":"information-you-choose-to-share","type":"text","heading":{"en":"Information you choose to share","ka":""},"body":{"en":"If you contact us by email or telephone, you may provide your name, contact details, and the information in your enquiry. These details are used to respond to your request and manage the related correspondence. Please share only information needed for your enquiry. The website itself does not provide customer accounts, payment forms, or an online checkout.","ka":""}},{"id":"browsing-information-and-cookies","type":"text","heading":{"en":"Browsing information and cookies","ka":""},"body":{"en":"Hosting and security services may process technical information such as an IP address, browser or device details, requested pages, and access times to deliver and protect the website. We have not added advertising trackers or optional analytics to these pages. The hosting platform may use essential cookies or similar technologies. You can manage cookies through your browser settings.","ka":""}},{"id":"external-services-and-photographs","type":"text","heading":{"en":"External services and photographs","ka":""},"body":{"en":"Some photographs are loaded from Wikimedia Commons, so your browser sends connection information to that service when requesting an image. Map, news-source, and other external links take you to separately operated websites. Email and telephone links open your own applications. Those services may process information under their own privacy policies.","ka":""}},{"id":"purposes-and-legal-grounds","type":"text","heading":{"en":"Purposes and legal grounds","ka":""},"body":{"en":"Information is used to answer enquiries, take steps you request before an agreement, operate and secure the website, and meet legal obligations. The relevant legal ground depends on the activity and may include a requested agreement, legitimate interests, a legal obligation, or consent. Where processing relies on consent, you may withdraw it.","ka":""}},{"id":"service-providers-and-retention","type":"text","heading":{"en":"Service providers and retention","ka":""},"body":{"en":"Website hosting and email services may involve service providers processing information outside Georgia. Contact us for details of the providers, destinations, and safeguards relevant to your enquiry.\n\nInformation should be retained only as long as needed for its purpose or applicable legal obligations. The nature of an enquiry, any ongoing relationship, and record-keeping requirements determine the relevant period.","ka":""}},{"id":"your-privacy-rights","type":"text","heading":{"en":"Your privacy rights","ka":""},"body":{"en":"Subject to applicable law, you may request information about processing, access to your data, correction, erasure or blocking, and a portable copy where available. You may also withdraw consent and raise a complaint with the competent data protection authority or a court. Send requests to office@badagoni.ge; information to verify your identity may be needed.","ka":""}},{"id":"changes-to-this-notice","type":"text","heading":{"en":"Changes to this notice","ka":""},"body":{"en":"This notice may be updated when the website or relevant practices change. The date shown beside this policy identifies its latest revision. Please contact us if you need further information about a particular use of your data.","ka":""}}]}}');
